@st.cache_data(show_spinner=False)
def generate_consumption_history(days: int = 180, seed: int = 42) -> pd.DataFrame:
    rng = np.random.default_rng(seed)
    end = pd.Timestamp(date.today()) - pd.Timedelta(days=1)
    dates = pd.date_range(end=end, periods=days, freq="D")
    rows: List[Dict] = []

    for _, s in STATIONS.iterrows():
        for d in dates:
            doy = d.dayofyear
            # Summer tourism peak + weekly operations pattern + random noise.
            seasonal = 1.0 + 0.26 * math.sin(2 * math.pi * (doy - 170) / 365.25)
            summer_boost = 1.15 if d.month in (6, 7, 8) else 1.0
            weekly = 1.04 if d.dayofweek in (4, 5, 6) else 0.98
            noise = rng.normal(1.0, 0.075)
            value = max(20, s.base_daily_t * seasonal * summer_boost * weekly * noise)
            rows.append({"date": d, "station": s.station, "consumption_t": round(value, 1)})
    return pd.DataFrame(rows)


def haversine_nm(lat1: float, lon1: float, lat2: float, lon2: float) -> float:
    r_km = 6371.0088
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dphi = math.radians(lat2 - lat1)
    dlambda = math.radians(lon2 - lon1)
    a = math.sin(dphi / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(dlambda / 2) ** 2
    km = 2 * r_km * math.asin(math.sqrt(a))
    return km / 1.852


def build_station_snapshot(history: pd.DataFrame, target_days: int, safety_days: int) -> pd.DataFrame:
    recent = (
        history.sort_values("date")
        .groupby("station")
        .tail(21)
        .copy()
    )
    stats = (
        recent.groupby("station")["consumption_t"]
        .agg(forecast_daily_t="mean", demand_std_t="std")
        .reset_index()
    )
    df = STATIONS.merge(stats, on="station", how="left")
    df["forecast_daily_t"] = df["forecast_daily_t"].round(1)
    df["days_cover"] = (df["current_stock_t"] / df["forecast_daily_t"]).round(1)
    df["safety_stock_t"] = (df["forecast_daily_t"] * safety_days).round(0)
    df["target_stock_t"] = np.minimum(df["tank_capacity_t"], df["forecast_daily_t"] * target_days).round(0)
    df["delivery_need_t"] = np.maximum(0, df["target_stock_t"] - df["current_stock_t"]).round(0)
    df["distance_nm"] = df.apply(lambda r: haversine_nm(HUB["lat"], HUB["lon"], r.lat, r.lon), axis=1).round(1)
    df["risk"] = pd.cut(
        df["days_cover"],
        bins=[-np.inf, safety_days, safety_days + 4, np.inf],
        labels=["Critical", "Watch", "Healthy"],
        right=False,
    )
    return df


def _ship_key(ship: str) -> str:
    return ship.lower().replace(" ", "_")


def init_ship_availability() -> None:
    """Create persistent calendar state for each vessel."""
    today = date.today()
    default_end = today + timedelta(days=30)
    for ship in FLEET["ship"]:
        key = _ship_key(ship)
        st.session_state.setdefault(f"active_{key}", True)
        st.session_state.setdefault(f"availability_{key}", (today, default_end))


def get_ship_availability() -> Dict[str, Dict]:
    """Read the vessel calendar controls from Streamlit session state."""
    result: Dict[str, Dict] = {}
    today = date.today()
    for ship in FLEET["ship"]:
        key = _ship_key(ship)
        active = bool(st.session_state.get(f"active_{key}", True))
        value = st.session_state.get(f"availability_{key}", (today, today + timedelta(days=30)))
        if isinstance(value, (tuple, list)):
            if len(value) >= 2:
                start_d, end_d = value[0], value[1]
            elif len(value) == 1:
                start_d = end_d = value[0]
            else:
                start_d, end_d = today, today + timedelta(days=30)
        else:
            start_d = end_d = value
        if pd.Timestamp(end_d) < pd.Timestamp(start_d):
            start_d, end_d = end_d, start_d
        result[ship] = {"active": active, "start": pd.Timestamp(start_d), "end": pd.Timestamp(end_d)}
    return result


def _distance_between(a_lat: float, a_lon: float, b_lat: float, b_lon: float) -> float:
    return haversine_nm(a_lat, a_lon, b_lat, b_lon)


def plan_voyages(
    snapshot: pd.DataFrame,
    planning_days: int,
    target_days: int,
    safety_days: int,
    port_hours: float,
    weather_delay_pct: float,
    availability: Dict[str, Dict],
    max_stops: int = 3,
) -> Tuple[pd.DataFrame, pd.DataFrame]:
    """Schedule all required replenishment voyages across the planning horizon.

    This is a rolling inventory-routing heuristic. It does not stop after the
    initial replenishment gap is covered. Instead, it projects continuous fuel
    consumption, determines when each station will next reach safety stock,
    and keeps scheduling repeat voyages until the horizon ends. Each voyage
    starts and ends in Lavrio and may serve several islands.
    """
    today_ts = pd.Timestamp(date.today()).normalize()
    horizon_end = today_ts + pd.Timedelta(days=planning_days, hours=23, minutes=59)

    station_lookup = snapshot.set_index("station")[["lat", "lon"]].to_dict("index")
    daily = snapshot.set_index("station")["forecast_daily_t"].astype(float).to_dict()
    initial_stock = snapshot.set_index("station")["current_stock_t"].astype(float).to_dict()
    safety_stock = snapshot.set_index("station")["safety_stock_t"].astype(float).to_dict()
    target_stock = snapshot.set_index("station")["target_stock_t"].astype(float).to_dict()
    tank_capacity = snapshot.set_index("station")["tank_capacity_t"].astype(float).to_dict()

    ship_state: Dict[str, Dict] = {}
    for i, row in FLEET.iterrows():
        cal = availability[row.ship]
        calendar_start = cal["start"].normalize() + pd.Timedelta(hours=6)
        calendar_end = cal["end"].normalize() + pd.Timedelta(hours=23, minutes=59)
        ship_state[row.ship] = {
            "available": max(today_ts + pd.Timedelta(hours=6 + i * 2), calendar_start),
            "available_until": min(calendar_end, horizon_end),
            "capacity": float(row.capacity_t),
            "speed": float(row.speed_kn),
            "active": bool(cal["active"]),
            "voyages_count": 0,
        }

    delivery_events: List[Dict] = []
    voyage_rows: List[Dict] = []
    stop_rows: List[Dict] = []
    trip_id = 1

    def projected_stock(station: str, at_ts: pd.Timestamp, extra_events: List[Dict] | None = None) -> float:
        elapsed_days = max(0.0, (at_ts - today_ts).total_seconds() / 86400.0)
        stock = initial_stock[station] - daily[station] * elapsed_days
        all_events = delivery_events + (extra_events or [])
        stock += sum(
            float(e["cargo_t"])
            for e in all_events
            if e["station"] == station and pd.Timestamp(e["eta"]) <= at_ts
        )
        return stock

    def next_due_time(station: str) -> pd.Timestamp:
        """Next time this station needs a new voyage, after already-planned calls."""
        station_events = [e for e in delivery_events if e["station"] == station]
        if station_events:
            start_ts = max(pd.Timestamp(e["eta"]) for e in station_events)
        else:
            start_ts = today_ts
        stock = projected_stock(station, start_ts)
        if stock <= safety_stock[station]:
            return start_ts
        hours_to_safety = (stock - safety_stock[station]) / max(daily[station], 1e-9) * 24.0
        return start_ts + pd.Timedelta(hours=hours_to_safety)

    def direct_roundtrip_finish(ship: str, station: str, dispatch: pd.Timestamp) -> pd.Timestamp:
        loc = station_lookup[station]
        nm = _distance_between(HUB["lat"], HUB["lon"], loc["lat"], loc["lon"])
        sailing_h = nm / ship_state[ship]["speed"] * (1 + weather_delay_pct / 100.0)
        return dispatch + pd.Timedelta(hours=2 * sailing_h + port_hours)

    # A conservative cap protects the UI from pathological scenarios while
    # allowing many repeat voyages in a 30-day horizon.
    for _ in range(240):
        due_map = {s: next_due_time(s) for s in snapshot["station"]}
        due_station, first_due = min(due_map.items(), key=lambda item: item[1])
        if first_due > horizon_end:
            break

        ship_options = []
        for ship, state in ship_state.items():
            if not state["active"] or state["available"] > state["available_until"]:
                continue
            loc = station_lookup[due_station]
            direct_nm = _distance_between(HUB["lat"], HUB["lon"], loc["lat"], loc["lon"])
            direct_h = direct_nm / state["speed"] * (1 + weather_delay_pct / 100.0)
            # Wait at Lavrio if possible and dispatch just in time. A six-hour
            # buffer gives the route builder room to combine nearby due calls.
            desired_dispatch = first_due - pd.Timedelta(hours=direct_h + 6)
            dispatch = max(state["available"], desired_dispatch, today_ts + pd.Timedelta(hours=6))
            if dispatch > state["available_until"] or dispatch > horizon_end:
                continue
            direct_finish = direct_roundtrip_finish(ship, due_station, dispatch)
            if direct_finish > state["available_until"] or direct_finish > horizon_end:
                continue
            direct_arrival = dispatch + pd.Timedelta(hours=direct_h)
            lateness_h = max(0.0, (direct_arrival - first_due).total_seconds() / 3600.0)
            ship_options.append((lateness_h, state["voyages_count"], direct_arrival, ship, dispatch))

        if not ship_options:
            # No vessel can fit another complete voyage in the remaining window.
            break

        _, _, _, ship, dispatch = min(ship_options)
        state = ship_state[ship]
        window_end = min(state["available_until"], horizon_end)
        cargo_remaining = state["capacity"]
        route_stations: List[str] = []
        route_deliveries: List[float] = []
        temp_events: List[Dict] = []
        temp_stop_rows: List[Dict] = []
        current_lat, current_lon = HUB["lat"], HUB["lon"]
        cursor = dispatch
        cumulative_nm = 0.0
        first_due_reference = first_due

        for stop_no in range(1, max_stops + 1):
            current_due = {s: next_due_time(s) for s in snapshot["station"] if s not in route_stations}
            if stop_no == 1:
                candidate_order = [due_station]
            else:
                # Bundle stations whose replenishment is coming due close to the
                # first call. Proximity then breaks ties to create sensible tours.
                bundle_cutoff = min(horizon_end, first_due_reference + pd.Timedelta(days=3.5))
                candidates = [s for s, d in current_due.items() if d <= bundle_cutoff]
                def score(s: str) -> Tuple[float, float]:
                    loc = station_lookup[s]
                    leg = _distance_between(current_lat, current_lon, loc["lat"], loc["lon"])
                    hours_until_due = (current_due[s] - cursor).total_seconds() / 3600.0
                    return (hours_until_due, leg)
                candidate_order = sorted(candidates, key=score)

            selected = None
            selected_payload = None
            for station in candidate_order:
                loc = station_lookup[station]
                leg_nm = _distance_between(current_lat, current_lon, loc["lat"], loc["lon"])
                travel_h = leg_nm / state["speed"] * (1 + weather_delay_pct / 100.0)
                eta = cursor + pd.Timedelta(hours=travel_h)
                if eta > horizon_end:
                    continue

                stock_at_eta = projected_stock(station, eta, temp_events)
                desired_cargo = max(0.0, target_stock[station] - max(0.0, stock_at_eta))
                storage_room = max(0.0, tank_capacity[station] - max(0.0, stock_at_eta))
                cargo = min(cargo_remaining, desired_cargo, storage_room)
                if cargo <= 50:
                    continue

                depart_stop = eta + pd.Timedelta(hours=port_hours)
                return_nm = _distance_between(loc["lat"], loc["lon"], HUB["lat"], HUB["lon"])
                return_h = return_nm / state["speed"] * (1 + weather_delay_pct / 100.0)
                earliest_return = depart_stop + pd.Timedelta(hours=return_h)
                if earliest_return > window_end:
                    continue

                selected = station
                selected_payload = (loc, leg_nm, eta, depart_stop, cargo, stock_at_eta)
                break

            if selected is None:
                break

            station = selected
            loc, leg_nm, eta, depart_stop, cargo, stock_at_eta = selected_payload
            due_ts = current_due.get(station, first_due_reference)
            cumulative_nm += leg_nm
            arrival_cover = max(0.0, stock_at_eta) / max(daily[station], 1e-9)
            temp_events.append({"station": station, "eta": eta, "cargo_t": float(cargo)})
            temp_stop_rows.append({
                "voyage": f"V{trip_id:02d}",
                "ship": ship,
                "stop": stop_no,
                "station": station,
                "cargo_t": round(cargo),
                "eta": eta,
                "depart": depart_stop,
                "leg_nm": round(leg_nm, 1),
                "cumulative_nm": round(cumulative_nm, 1),
                "arrival_cover_days": round(arrival_cover, 1),
                "due_by": due_ts,
                "service_status": "On time" if eta <= due_ts else "After safety threshold",
            })
            route_stations.append(station)
            route_deliveries.append(float(cargo))
            cargo_remaining -= cargo
            cursor = depart_stop
            current_lat, current_lon = loc["lat"], loc["lon"]
            if cargo_remaining <= 50:
                break

        if not route_stations:
            # This ship cannot create a feasible call; remove it from the
            # remainder of the horizon to prevent an endless loop.
            state["available"] = window_end + pd.Timedelta(minutes=1)
            continue

        return_leg_nm = _distance_between(current_lat, current_lon, HUB["lat"], HUB["lon"])
        cumulative_nm += return_leg_nm
        return_h = return_leg_nm / state["speed"] * (1 + weather_delay_pct / 100.0)
        ret = cursor + pd.Timedelta(hours=return_h)
        if ret > window_end:
            state["available"] = window_end + pd.Timedelta(minutes=1)
            continue

        voyage = f"V{trip_id:02d}"
        total_cargo = float(sum(route_deliveries))
        route_text = "Lavrio → " + " → ".join(route_stations) + " → Lavrio"
        late_calls = sum(1 for r in temp_stop_rows if r["service_status"] != "On time")
        voyage_rows.append({
            "voyage": voyage,
            "ship": ship,
            "route": route_text,
            "stops": len(route_stations),
            "cargo_t": round(total_cargo),
            "capacity_t": round(state["capacity"]),
            "utilization_pct": round(total_cargo / state["capacity"] * 100, 1),
            "dispatch": dispatch,
            "return": ret,
            "distance_nm": round(cumulative_nm, 1),
            "duration_h": round((ret - dispatch).total_seconds() / 3600, 1),
            "priority": "Safety risk" if late_calls else "Planned",
        })
        stop_rows.extend(temp_stop_rows)
        delivery_events.extend(temp_events)
        state["available"] = ret + pd.Timedelta(hours=3)
        state["voyages_count"] += 1
        trip_id += 1

    voyages_df = pd.DataFrame(voyage_rows)
    stops_df = pd.DataFrame(stop_rows)
    return voyages_df, stops_df


def build_planned_stock_projection(
    snapshot: pd.DataFrame,
    stops: pd.DataFrame,
    planning_days: int,
) -> pd.DataFrame:
    """Daily inventory trajectory including all scheduled voyage deliveries."""
    today_ts = pd.Timestamp(date.today()).normalize()
    rows: List[Dict] = []
    stop_records = [] if stops.empty else stops.to_dict("records")
    for _, r in snapshot.iterrows():
        for day_no in range(planning_days + 1):
            ts = today_ts + pd.Timedelta(days=day_no, hours=12)
            delivered = sum(
                float(e["cargo_t"])
                for e in stop_records
                if e["station"] == r.station and pd.Timestamp(e["eta"]) <= ts
            )
            consumed = float(r.forecast_daily_t) * max(0.0, (ts - today_ts).total_seconds() / 86400.0)
            raw_stock = float(r.current_stock_t) + delivered - consumed
            rows.append({
                "day": day_no,
                "date": ts,
                "station": r.station,
                "stock_t": max(0.0, raw_stock),
                "safety_t": float(r.safety_stock_t),
                "tank_capacity_t": float(r.tank_capacity_t),
            })
    return pd.DataFrame(rows)


SHIP_COLORS = {
    "PPC Star Delos": [56, 189, 248, 225],
    "PPC Star Naxos": [34, 197, 94, 225],
    "PPC Star Chios": [245, 158, 11, 225],
}


def _bearing_degrees(lon1: float, lat1: float, lon2: float, lat2: float) -> float:
    """Approximate screen bearing for rotating an east-pointing arrow glyph."""
    dx = lon2 - lon1
    dy = lat2 - lat1
    return -math.degrees(math.atan2(dy, dx))


def render_voyage_map(
    voyages: pd.DataFrame,
    stops: pd.DataFrame,
    selected_voyages: List[str] | None = None,
    height: int = 500,
) -> None:
    """Draw complete routes, direction arrows, and vessel-coloured labels."""
    point_rows = [{"name": HUB["name"], "lat": HUB["lat"], "lon": HUB["lon"], "kind": "Hub", "size": 1000}]
    for _, r in snapshot.iterrows():
        point_rows.append({"name": r.station, "lat": r.lat, "lon": r.lon, "kind": "Station", "size": 650})
    points = pd.DataFrame(point_rows)

    path_rows: List[Dict] = []
    label_rows: List[Dict] = []
    arrow_rows: List[Dict] = []
    if not voyages.empty and not stops.empty:
        subset = voyages if not selected_voyages else voyages[voyages["voyage"].isin(selected_voyages)]
        lookup = snapshot.set_index("station")[["lat", "lon"]].to_dict("index")
        for _, v in subset.iterrows():
            v_stops = stops[stops["voyage"] == v.voyage].sort_values("stop")
            coords = [[HUB["lon"], HUB["lat"]]]
            for _, s in v_stops.iterrows():
                loc = lookup[s.station]
                coords.append([loc["lon"], loc["lat"]])
            coords.append([HUB["lon"], HUB["lat"]])
            color = SHIP_COLORS.get(v.ship, [125, 211, 252, 225])
            path_rows.append({"path": coords, "color": color, "label": f"{v.voyage} · {v.ship}", "route": v.route})

            # Route label near the middle call.
            mid = coords[max(1, min(len(coords) - 2, len(coords) // 2))]
            label_rows.append({"lon": mid[0], "lat": mid[1], "label": f"{v.voyage} · {v.ship}", "color": color})

            # Direction arrow on every leg, including the return to Lavrio.
            for leg_no, (a, b) in enumerate(zip(coords[:-1], coords[1:]), start=1):
                frac = 0.55
                arrow_rows.append({
                    "lon": a[0] + frac * (b[0] - a[0]),
                    "lat": a[1] + frac * (b[1] - a[1]),
                    "arrow": "➤",
                    "angle": _bearing_degrees(a[0], a[1], b[0], b[1]),
                    "color": color,
                    "label": f"{v.voyage} · {v.ship} · leg {leg_no}",
                })

    layers = [
        pdk.Layer(
            "ScatterplotLayer", points, get_position="[lon, lat]", get_radius="size",
            radius_min_pixels=6, radius_max_pixels=13,
            get_fill_color="[56, 189, 248, 220]", get_line_color="[255,255,255,160]",
            line_width_min_pixels=1, stroked=True, pickable=True,
        ),
        pdk.Layer(
            "TextLayer", points, get_position="[lon, lat]", get_text="name",
            get_size=13, get_color="[232,240,248,235]", get_pixel_offset="[0, -18]",
            get_text_anchor="'middle'", pickable=False,
        ),
    ]
    if path_rows:
        layers.insert(0, pdk.Layer(
            "PathLayer", pd.DataFrame(path_rows), get_path="path", get_color="color",
            width_min_pixels=3, get_width=4, pickable=True,
        ))
        layers.append(pdk.Layer(
            "TextLayer", pd.DataFrame(arrow_rows), get_position="[lon, lat]", get_text="arrow",
            get_size=22, get_color="color", get_angle="angle",
            get_text_anchor="'middle'", get_alignment_baseline="'center'", pickable=True,
        ))
        layers.append(pdk.Layer(
            "TextLayer", pd.DataFrame(label_rows), get_position="[lon, lat]", get_text="label",
            get_size=14, get_color="color", get_pixel_offset="[0, 18]",
            get_text_anchor="'middle'", pickable=True,
        ))

    deck = pdk.Deck(
        layers=layers,
        initial_view_state=pdk.ViewState(latitude=37.65, longitude=24.65, zoom=5.5, pitch=18),
        tooltip={"text": "{name}{label}\n{route}"},
        map_style=None,
    )
    st.pydeck_chart(deck, width="stretch", height=height)


def render_ship_legend() -> None:
    """Consistent vessel colour legend for all route maps."""
    items = []
    for ship in FLEET["ship"]:
        rgb = SHIP_COLORS[ship][:3]
        status = "Available" if ship_availability[ship]["active"] else "Unavailable"
        items.append(
            f'<div style="display:flex;align-items:center;gap:.5rem;white-space:nowrap;">'
            f'<span style="width:12px;height:12px;border-radius:999px;background:rgb({rgb[0]},{rgb[1]},{rgb[2]});display:inline-block;box-shadow:0 0 0 2px rgba({rgb[0]},{rgb[1]},{rgb[2]},.18);"></span>'
            f'<span style="color:#dbe8f5;font-size:.83rem"><b>{ship}</b> · {status}</span></div>'
        )
    st.markdown(
        '<div style="display:flex;gap:1rem;flex-wrap:wrap;padding:.45rem .1rem .65rem .1rem">' + ''.join(items) + '</div>',
        unsafe_allow_html=True,
    )

def status_pill(risk: str) -> str:
    cls = {"Healthy": "pill-good", "Watch": "pill-warn", "Critical": "pill-bad"}.get(risk, "pill-info")
    return f'<span class="{cls}">{risk}</span>'


